#include "g++-2/stl_list_shared.h"

typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, __PRETTY_FUNCTION__, 0)

extern "C" void __assert(const char *, const char *, int);
#define assert(x) ((x) ? (void)0 : __assert(#x, __FILE__, __LINE__))

class stringx {
  void *rep;
};

stringx operator+(const stringx &, const char *);
stringx operator+(const stringx &, const stringx &);
void error(const stringx &);

class vm_thread;

class vm_stack {
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  bool push(const char *, int);
};

class script_object;
class script_callback;

class vm_executable {
  script_object *owner;
  stringx name;
  stringx fullname;
  char parameters[12];
  int parms_stacksize;
  bool static_func;
  bool linked;
  unsigned short *buffer;
  int buffer_len;
public:
  const stringx &get_fullname() const { return fullname; }
  int get_parms_stacksize() const { return parms_stacksize; }
  const unsigned short *get_start() const { return buffer; }
};

class script_object {
public:
  class instance;
};

class vm_thread {
  script_object::instance *inst;
  const vm_executable *ex;
  unsigned int flags;
  vm_stack dstack;
  const unsigned short *PC;
public:
  vm_thread(script_object::instance *, const vm_executable *, int,
            script_callback *);
  void set_suspended(bool);
  vm_stack &get_data_stack() { return dstack; }
  friend class script_object::instance;
};

inline void construct_thread_pointer(vm_thread **p, vm_thread *const &v)
{
  if (p)
    new((void *)p) vm_thread *(v);
}

class script_thread_list {
public:
  typedef _List_node<vm_thread *> node_type;
  typedef _List_iterator<vm_thread *, vm_thread *&, vm_thread **> iterator;
  node_type *sentinel;
private:
  node_type *create_node(vm_thread *const &value)
  {
    __default_alloc_object *raw = allocator_pool._S_free_list[1];
    node_type *node;
    if (!raw)
      node = static_cast<node_type *>(allocator_refill(16));
    else {
      allocator_pool._S_free_list[1] = raw->_M_free_list_link;
      node = reinterpret_cast<node_type *>(raw);
    }
    construct_thread_pointer(&node->_M_data, value);
    return node;
  }
  iterator insert(iterator position, vm_thread *const &value)
  {
    node_type *node = create_node(value);
    node->_M_next = position._M_node;
    node->_M_prev = static_cast<node_type *>(position._M_node)->_M_prev;
    static_cast<node_type *>(node->_M_prev)->_M_next = node;
    static_cast<node_type *>(position._M_node)->_M_prev = node;
    return iterator(node);
  }
public:
  iterator end() { return iterator(sentinel); }
  void push_back(vm_thread *const &value) { insert(end(), value); }
};

class script_object::instance {
  stringx name;
  char data[12];
  script_thread_list threads;
  bool suspended;
public:
  const stringx &get_name() const { return name; }
  vm_thread *add_thread(script_callback *, const vm_executable *, const char *);
};

vm_thread* script_object::instance::add_thread( script_callback* cb, const vm_executable* ex, const char* parms )
  {
  vm_thread* nt = NEW vm_thread( this, ex, 256, cb );
  assert(nt != NULL);
  threads.push_back( nt );
  // if this script object instance is suspended, we must suspend any thread
  // that is added here
  if ( suspended )
    nt->set_suspended( true );
  if ( parms && !nt->get_data_stack().push( parms, ex->get_parms_stacksize() ) )
    error( get_name() + ": stack overflow spawning " + ex->get_fullname() );
  nt->PC = ex->get_start();
  return nt;
  }
